using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// All art comes from PixelArtData (base64 PNGs generated by Tools/generate_art.py), decoded at runtime,
/// so there is nothing to import. Every sprite is 16 pixels per world unit.
/// </summary>
public static class SpriteFactory
{
    public const float PPU = 16f;
    static readonly Dictionary<string, Sprite> cache = new Dictionary<string, Sprite>();

    static Texture2D Decode(string name, PixelArtData.Entry e)
    {
        var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
        tex.LoadImage(Convert.FromBase64String(e.b64));
        tex.filterMode = FilterMode.Point;
        tex.wrapMode = (name.StartsWith("tile_") || name.StartsWith("pipe_")) ? TextureWrapMode.Repeat : TextureWrapMode.Clamp;
        tex.name = name;
        return tex;
    }

    /// <summary>A sprite by name, e.g. "knight_idle". The pivot is bottom-centre for characters, centre for tiles/icons.</summary>
    public static Sprite Get(string name)
    {
        Sprite s;
        if (cache.TryGetValue(name, out s) && s != null) return s;
        PixelArtData.Entry e;
        if (!PixelArtData.All.TryGetValue(name, out e))
        {
            Debug.LogError("[SpriteFactory] missing sprite: " + name);
            return Square(Color.magenta);
        }
        var tex = Decode(name, e);
        s = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(e.px, e.py), PPU, 0, SpriteMeshType.FullRect);
        s.name = name;
        cache[name] = s;
        return s;
    }

    /// <summary>name_1 .. name_n</summary>
    public static Sprite[] Frames(string prefix, int count)
    {
        var f = new Sprite[count];
        for (int i = 0; i < count; i++) f[i] = Get(prefix + (i + 1));
        return f;
    }

    /// <summary>9-slice version for UI panels/buttons (100 px per unit so the UI scaler treats 1 sprite px = 1 UI px).</summary>
    public static Sprite GetSliced(string name, int border)
    {
        string key = name + "#s" + border;
        Sprite s;
        if (cache.TryGetValue(key, out s) && s != null) return s;
        PixelArtData.Entry e;
        if (!PixelArtData.All.TryGetValue(name, out e)) return Square(Color.magenta);
        var tex = Decode(name, e);
        s = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f, 0,
                          SpriteMeshType.FullRect, new Vector4(border, border, border, border));
        cache[key] = s;
        return s;
    }

    /// <summary>1x1 world-unit solid square.</summary>
    public static Sprite Square(Color color)
    {
        string key = "sq" + ColorUtility.ToHtmlStringRGBA(color);
        Sprite s;
        if (cache.TryGetValue(key, out s) && s != null) return s;
        var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
        tex.filterMode = FilterMode.Point;
        tex.SetPixel(0, 0, color);
        tex.Apply();
        s = Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
        cache[key] = s;
        return s;
    }
}

/// <summary>Tiny 5x7 bitmap font (glyphs in PixelFontData). Gives crisp pixel text for name tags, titles and banners.</summary>
public static class PixelFont
{
    public static float TextWidthPixels(string text) { return string.IsNullOrEmpty(text) ? 2 : text.Length * 6 - 1 + 2; }

    /// <summary>Renders text (upper-cased; unknown characters become '?') into a new sprite with a 1px outline.</summary>
    public static Sprite MakeSprite(string text, Color fill, Color outline, float pixelsPerUnit)
    {
        string t = string.IsNullOrEmpty(text) ? " " : text.ToUpperInvariant();
        int n = t.Length;
        int w = n * 6 - 1 + 2, h = 9;
        var on = new bool[w, h];
        for (int i = 0; i < n; i++)
        {
            string g;
            if (!PixelFontData.Glyphs.TryGetValue(t[i], out g)) g = PixelFontData.Glyphs['?'];
            string[] rows = g.Split('|');
            for (int r = 0; r < 7; r++)
                for (int c = 0; c < 5; c++)
                    if (rows[r][c] == '#') on[1 + i * 6 + c, 1 + (6 - r)] = true;
        }

        var px = new Color32[w * h];
        Color32 clear = new Color32(0, 0, 0, 0);
        for (int i = 0; i < px.Length; i++) px[i] = clear;
        if (outline.a > 0f)
        {
            Color32 o = outline;
            for (int x = 0; x < w; x++)
                for (int y = 0; y < h; y++)
                {
                    if (on[x, y]) continue;
                    bool near = (x > 0 && on[x - 1, y]) || (x < w - 1 && on[x + 1, y]) || (y > 0 && on[x, y - 1]) || (y < h - 1 && on[x, y + 1]);
                    if (near) px[y * w + x] = o;
                }
        }
        Color32 f = fill;
        for (int x = 0; x < w; x++)
            for (int y = 0; y < h; y++)
                if (on[x, y]) px[y * w + x] = f;

        var tex = new Texture2D(w, h, TextureFormat.RGBA32, false);
        tex.filterMode = FilterMode.Point;
        tex.wrapMode = TextureWrapMode.Clamp;
        tex.SetPixels32(px);
        tex.Apply();
        return Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f), pixelsPerUnit, 0, SpriteMeshType.FullRect);
    }
}
